import { useEffect, useMemo, useRef, useState } from "react";
import { addCalendarDays, type CivilTimeOccurrence } from "@lancerlogin/shared/civil-time";
import { api } from "./dashboard-api";
import { OutreachClock } from "./outreach-clock";
import { ActivityPublicationControls, OutreachEventScheduleFields, type OutreachActivityPublication, type OutreachEventSchedule, type OutreachPublicationProviders } from "./outreach-activity-publication";
import { useModalFocus } from "./modal-focus";
import { OutreachPublicFormSettings } from "./outreach-public-settings";
import { BrowserViewIcon } from "./browser-view-icon";
import { groupOutreachParticipation, loadOutreachPages as readOutreachPages, outreachEntrySource } from "./outreach-participation";

type ActivityMode = "event" | "team" | "task";
type OutreachLabel = { id: string; name: string; archived: boolean; revision: number };
type Team = { id: string; name: string; number: string; program: string; archived: boolean; revision: number; participantCount?: number; countedMinutes?: number };
type Activity = { id: string; mode: ActivityMode; labelIds: string[]; labels: OutreachLabel[]; serviceDate: string; teamId: string | null; title: string; description: string; location: string; impactRelevant: boolean; archived: boolean; revision: number } & OutreachEventSchedule;
type ActivityApi = Omit<Activity, "mode" | "labelIds" | "labels"> & { mode?: ActivityMode; categoryId?: string; labelIds?: string[]; labels?: OutreachLabel[] };
type Member = { id: string; label: string; externalId: string; active: boolean };
type EntryContext = { reportingDays: number; reopenHours: number; revision: number; timeZone: string; today: string };
type Entry = { id: string; memberId: string; activityId: string; revision: number; status: "counted" | "void"; memberName: string; externalId: string; activityTitle: string; categoryName?: string; teamName: string | null; serviceDate: string; timeZone?: string; startLocal: string; endLocal: string; startOccurrence?: CivilTimeOccurrence | null; endOccurrence?: CivilTimeOccurrence | null; durationMinutes: number; taskNotes: string; attribution: string; staffReason?: string | null };
type ReopenWindow = { id: string; activityId: string | null; activityTitle: string | null; activityServiceDate: string | null; startsMs: number; expiresMs: number; reason: string; revoked: boolean; revision: number; active: boolean };
type Correction = { id: string; channel: "public" | "discord"; memberName: string; externalId: string; activityId?: string | null; entryId: string | null; claimedServiceDate: string | null; message: string; status: "open" | "resolved"; revision: number; createdAt: string; entryRevision: number | null; entryStatus: "counted" | "void" | null; entryMemberId: string | null; entryActivityId: string | null; entryServiceDate: string | null; startLocal: string | null; endLocal: string | null; startOccurrence: CivilTimeOccurrence | null; endOccurrence: CivilTimeOccurrence | null; taskNotes: string | null; activityTitle: string | null; resolutionAction: string | null; resolutionNote: string | null };
type Publication = OutreachActivityPublication;
type PublicationProviders = OutreachPublicationProviders;
type Page<T> = { items: T[]; nextCursor: string | null };
const loadOutreachPages = <T,>(path: string, signal?: AbortSignal) => readOutreachPages<T>(path, (query, nextSignal) => api<Page<T>>(query, { signal: nextSignal }), signal);
type Tab = "activities" | "entries" | "settings";
type ActivityView = "calendar" | "table";
const minutes = (value: number) => `${value.toLocaleString()} min (${(value / 60).toFixed(2)} hr)`;
const activityTypes: Array<{ value: ActivityMode; label: string }> = [{ value: "event", label: "Event" }, { value: "team", label: "Team support" }, { value: "task", label: "Other service" }];
const activityTypeLabel = (mode: ActivityMode) => activityTypes.find((item) => item.value === mode)?.label ?? mode;
const normalizeActivity = (item: ActivityApi): Activity => ({ ...item, mode: item.mode ?? (item.categoryId === "team-support" ? "team" : item.categoryId === "other-service" ? "task" : "event"), labelIds: Array.isArray(item.labelIds) ? item.labelIds : [], labels: Array.isArray(item.labels) ? item.labels : [], eventStartLocal: item.eventStartLocal ?? null, eventEndLocal: item.eventEndLocal ?? null, eventStartOccurrence: item.eventStartOccurrence ?? null, eventEndOccurrence: item.eventEndOccurrence ?? null });
const activityPayload = (draft: { mode: ActivityMode; labelIds: string[]; teamId: string; serviceDate: string; title: string; description: string; location: string; impactRelevant: boolean }) => ({ ...draft, teamId: draft.mode === "team" ? draft.teamId : null, archived: false });
const dayKey = (date: Date) => `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, "0")}-${String(date.getDate()).padStart(2, "0")}`;
const parseServiceDate = (value: string) => { const [year, month, day] = value.split("-").map(Number); return new Date(year!, month! - 1, day!, 12); };
export const outreachActivityViewKey = "lancerlogin-outreach-activity-view";
export const outreachActivityVisibilityKey = "lancerlogin-outreach-activity-visibility";
const savedActivityView = (): ActivityView => { try { return window.localStorage.getItem(outreachActivityViewKey) === "table" ? "table" : "calendar"; } catch { return "calendar"; } };
const savedActivityVisibility = (): ActivityMode[] => { try { const raw = window.localStorage.getItem(outreachActivityVisibilityKey); if (raw === null) return ["event"]; const parsed = JSON.parse(raw); return Array.isArray(parsed) ? parsed.filter((item): item is ActivityMode => activityTypes.some((type) => type.value === item)) : ["event"]; } catch { return ["event"]; } };

export function OutreachWorkspace({ activityId, onOpenActivity, onCloseActivity, isAdmin = false }: { isAdmin?: boolean; activityId?: string; onOpenActivity?: (id: string) => void; onCloseActivity?: () => void } = {}) {
  const [tab, setTab] = useState<Tab>("activities"); const [labels, setLabels] = useState<OutreachLabel[]>([]); const [teams, setTeams] = useState<Team[]>([]); const [activities, setActivities] = useState<Activity[]>([]); const [members, setMembers] = useState<Member[]>([]); const [entries, setEntries] = useState<Entry[]>([]); const [windows, setWindows] = useState<ReopenWindow[]>([]); const [corrections, setCorrections] = useState<Correction[]>([]); const [publications, setPublications] = useState<Publication[]>([]); const [publicationProviders, setPublicationProviders] = useState<PublicationProviders>({ google_calendar: false, discord: false }); const [context, setContext] = useState<EntryContext>(); const [busy, setBusy] = useState(false); const [selectedActivityId, setSelectedActivityId] = useState(""); const [notice, setNotice] = useState<{ tone: "success" | "error"; text: string }>(); const noticeRef = useRef<HTMLParagraphElement>(null);
  async function load() {
    setBusy(true); setNotice(undefined);
    try {
      const [labelPage, teamPage, activityPage, memberPage, entryPage, windowPage, correctionPage, publicationPage, providers, nextContext] = await Promise.all([
        loadOutreachPages<OutreachLabel>("/admin/hours/labels?archived=all&limit=100"), loadOutreachPages<Team>("/admin/hours/teams?archived=all&limit=100"), loadOutreachPages<ActivityApi>("/admin/hours/activities?archived=all&limit=100"), loadOutreachPages<Member>("/admin/hours/member-choices?active=all&limit=100"), api<Page<Entry>>("/admin/hours/entries?limit=100"), loadOutreachPages<ReopenWindow>("/admin/hours/reopen-windows?limit=100"), loadOutreachPages<Correction>("/admin/hours/corrections?status=all&limit=100"), api<Page<Publication>>("/admin/hours/publications"), api<PublicationProviders>("/admin/hours/publication-providers"), api<EntryContext>("/admin/hours/context"),
      ]);
      setLabels(labelPage); setTeams(teamPage); setActivities(activityPage.map(normalizeActivity)); setMembers(memberPage); setEntries(entryPage.items); setWindows(windowPage); setCorrections(correctionPage); setPublications(publicationPage.items); setPublicationProviders(providers); setContext(nextContext);
    } catch (error) { setNotice({ tone: "error", text: (error as Error).message }); throw error; }
    finally { setBusy(false); }
  }
  useEffect(() => { void load().catch(() => undefined); }, []);
  useEffect(() => { if (notice) window.requestAnimationFrame(() => noticeRef.current?.focus()); }, [notice]);
  useEffect(() => { if (activityId) setTab("activities"); }, [activityId]);
  const activeTeams = teams.filter((item) => !item.archived);
  const openCorrections = corrections.filter((item) => item.status === "open");
  const updateLabel = (updated: OutreachLabel) => { setLabels((current) => current.map((item) => item.id === updated.id ? updated : item)); setActivities((current) => current.map((activity) => ({ ...activity, labels: activity.labels.map((label) => label.id === updated.id ? updated : label) }))); };
  const selectedId = activityId ?? selectedActivityId;
  const selected = activities.find((item) => item.id === selectedId);
  const openActivity = (id: string) => { if (onOpenActivity) onOpenActivity(id); else { setSelectedActivityId(id); setTab("activities"); } };
  const closeActivity = () => { if (onCloseActivity) onCloseActivity(); else setSelectedActivityId(""); };
  if (selectedId && tab === "activities") return <section className="outreach-workspace meeting-detail-workspace outreach-detail-workspace" aria-labelledby={`outreach-activity-${selectedId}`}>
    <nav className="meeting-detail-navigation" aria-label="Outreach activity detail navigation"><button className="ui-button" type="button" onClick={closeActivity}>Back to Activities</button><label>Switch activity<select className="ui-control ui-native-select" value={selectedId} onChange={(event) => openActivity(event.target.value)}>{activities.map((item) => <option key={item.id} value={item.id}>{item.serviceDate} - {item.title}</option>)}</select></label><button className="ui-button" type="button" onClick={() => { closeActivity(); setTab("entries"); }}>Submission Log</button></nav>
    {notice && <p ref={noticeRef} tabIndex={-1} className="ui-status settings-notice" data-tone={notice.tone} role={notice.tone === "error" ? "alert" : "status"}>{notice.text}</p>}
    {busy ? <p className="ui-status" role="status">Loading Outreach activity...</p> : selected && context ? <ActivityDetail key={`${selected.id}:${selected.revision}`} activity={selected} activities={activities} labels={labels.filter((item) => !item.archived)} members={members} windows={windows.filter((item) => item.activityId === selected.id)} corrections={corrections.filter((item) => (item.activityId ?? item.entryActivityId) === selected.id)} publication={publications.find((item) => item.activityId === selected.id)} publicationProviders={publicationProviders} context={context} onChanged={load} close={closeActivity} setNotice={setNotice} /> : <article className="ui-card outreach-stack"><h1 id={`outreach-activity-${selectedId}`}>Activity unavailable</h1><p>Choose another activity or return to Activities.</p></article>}
  </section>;
  const tabLabel = (item: Tab) => item === "entries" ? "Submission Log" : item === "settings" ? "Settings" : "Activities";
  return <section className="outreach-workspace operational-browser-page" aria-labelledby="outreach-title" data-walkthrough-page="outreach" data-walkthrough-ready={context && !busy ? "true" : undefined} tabIndex={-1}><div className="page-intro operational-page-intro"><h1 id="outreach-title">Outreach Participation</h1><p>Plan dated activities, review member submissions, and recover mistakes. Open Reports for participation totals.</p><div className="outreach-page-actions"><nav className="ui-control-group outreach-tabs" aria-label="Outreach sections">{(["activities", "entries", "settings"] as Tab[]).map((item) => <button className="ui-button" key={item} type="button" aria-pressed={tab === item} data-walkthrough={item === "entries" ? "outreach-submission-log" : undefined} onClick={() => setTab(item)}>{tabLabel(item)}</button>)}</nav>{openCorrections.length > 0 && <CorrectionInbox items={openCorrections} onOpenActivity={openActivity} />}</div></div>{notice && <p ref={noticeRef} tabIndex={-1} className="ui-status settings-notice" data-tone={notice.tone} role={notice.tone === "error" ? "alert" : "status"}>{notice.text}</p>}{busy && <p className="ui-status" role="status">Loading Outreach records...</p>}
    {!busy && tab === "settings" && <div className="outreach-stack"><OutreachCatalogPanels labels={labels} teams={teams} onTeamsChanged={load} onLabelCreated={(created) => setLabels((current) => [...current, created])} onLabelChange={updateLabel} setNotice={setNotice} />{isAdmin && <OutreachPublicFormSettings />}</div>}
    {!busy && tab === "activities" && context && <ActivityPanel items={activities} labels={labels} teams={activeTeams} members={members} windows={windows} corrections={corrections} publications={publications} publicationProviders={publicationProviders} context={context} selectedActivityId={selectedActivityId} setSelectedActivityId={openActivity} onChanged={load} setNotice={setNotice} />}
    {!busy && tab === "entries" && <SubmissionPanel items={entries} />}
  </section>;
}

function TeamPanel({ items, onChanged, setNotice }: { items: Team[]; onChanged: () => Promise<void>; setNotice: (value: { tone: "success" | "error"; text: string }) => void }) {
  const [draft, setDraft] = useState({ name: "", number: "", program: "" }); const [adding, setAdding] = useState(false); const [saving, setSaving] = useState(false); const dialog = useRef<HTMLElement>(null);
  const close = () => { setAdding(false); setDraft({ name: "", number: "", program: "" }); };
  useModalFocus(dialog, adding, saving, close);
  async function create(event: React.FormEvent) { event.preventDefault(); setSaving(true); try { await api("/admin/hours/teams", { method: "POST", body: JSON.stringify({ ...draft, archived: false }) }); close(); await onChanged(); setNotice({ tone: "success", text: "Supported team created." }); } catch (error) { setNotice({ tone: "error", text: (error as Error).message }); } finally { setSaving(false); } }
  async function archive(item: Team) { setSaving(true); try { await api(`/admin/hours/teams/${encodeURIComponent(item.id)}`, { method: "PATCH", body: JSON.stringify({ revision: item.revision, archived: !item.archived }) }); await onChanged(); setNotice({ tone: "success", text: item.archived ? "Supported team reopened." : "Supported team archived." }); } catch (error) { setNotice({ tone: "error", text: (error as Error).message }); } finally { setSaving(false); } }
  return <section className="outreach-stack" aria-labelledby="outreach-teams-title"><div className="panel-heading outreach-catalog-heading"><div><h2 id="outreach-teams-title">Supported teams</h2><p>Maintain the teams available for team-support activities.</p></div><button className="ui-button ui-button--primary" type="button" aria-haspopup="dialog" aria-expanded={adding} onClick={() => setAdding(true)}>Add team</button></div>{items.map((item) => <article className="ui-card outreach-row" key={item.id}><div><strong>{item.name}</strong><p>{[item.number, item.program].filter(Boolean).join(" - ") || "No number or program"}{item.archived ? " - archived" : ""}</p><small>{minutes(item.countedMinutes ?? 0)} from {item.participantCount ?? 0} participants</small></div><button className="ui-button" type="button" disabled={saving} onClick={() => void archive(item)}>{item.archived ? "Reopen" : "Archive"}</button></article>)}{!items.length && <p className="empty-state">No supported teams yet.</p>}{adding && <div className="dialog-backdrop"><section ref={dialog} className="meeting-management-dialog outreach-catalog-dialog ui-dialog" role="dialog" aria-modal="true" aria-labelledby="outreach-add-team-title" tabIndex={-1}><div className="dialog-heading"><div><h2 id="outreach-add-team-title">Add supported team</h2><p>Add a team that staff can associate with Outreach activities.</p></div><button className="ui-button" type="button" aria-label="Close add team dialog" disabled={saving} onClick={close}>×</button></div><form className="ui-form outreach-stack" onSubmit={create}><label>Team name<input data-modal-initial-focus required maxLength={150} value={draft.name} onChange={(event) => setDraft({ ...draft, name: event.target.value })} /></label><div className="form-grid"><label>Team number<input maxLength={32} value={draft.number} onChange={(event) => setDraft({ ...draft, number: event.target.value })} /></label><label>Program<input maxLength={100} value={draft.program} onChange={(event) => setDraft({ ...draft, program: event.target.value })} /></label></div><div className="dialog-actions"><button className="ui-button" type="button" disabled={saving} onClick={close}>Cancel</button><button className="ui-button ui-button--primary" disabled={saving || !draft.name.trim()}>{saving ? "Adding..." : "Add team"}</button></div></form></section></div>}</section>;
}

function ActivityPanel({ items, labels, teams, members, windows, corrections, publications, publicationProviders, context, selectedActivityId, setSelectedActivityId, onChanged, setNotice }: { items: Activity[]; labels: OutreachLabel[]; teams: Team[]; members: Member[]; windows: ReopenWindow[]; corrections: Correction[]; publications: Publication[]; publicationProviders: PublicationProviders; context: EntryContext; selectedActivityId: string; setSelectedActivityId: (id: string) => void; onChanged: () => Promise<void>; setNotice: (value: { tone: "success" | "error"; text: string }) => void }) {
  const [creating, setCreating] = useState(false); const [view, setView] = useState<ActivityView>(savedActivityView); const [visibleModes, setVisibleModes] = useState<ActivityMode[]>(savedActivityVisibility); const [calendarOffset, setCalendarOffset] = useState(0); const [search, setSearch] = useState("");
  const activeLabels = labels.filter((item) => !item.archived); const selectedActivity = items.find((item) => item.id === selectedActivityId);
  const visibleItems = useMemo(() => items.filter((item) => visibleModes.includes(item.mode)), [items, visibleModes]);
  const days = useMemo(() => { const currentWeek = parseServiceDate(context.today); currentWeek.setDate(currentWeek.getDate() - currentWeek.getDay()); const start = new Date(currentWeek); start.setDate(start.getDate() - 7 + calendarOffset * 35); return Array.from({ length: 35 }, (_, index) => { const date = new Date(start); date.setDate(start.getDate() + index); return date; }); }, [calendarOffset, context.today]);
  const calendarItems = useMemo(() => new Map(days.map((day) => [dayKey(day), visibleItems.filter((item) => item.serviceDate === dayKey(day)).sort((left, right) => (left.eventStartLocal ?? "").localeCompare(right.eventStartLocal ?? "") || left.title.localeCompare(right.title))])), [days, visibleItems]);
  const filtered = useMemo(() => { const query = search.trim().toLocaleLowerCase(); const matches = query ? visibleItems.filter((item) => [item.title, item.serviceDate, activityTypeLabel(item.mode), item.description, item.location, item.archived ? "archived" : "active", item.labels.map((label) => label.name).join(" "), item.teamId ? teams.find((team) => team.id === item.teamId)?.name ?? "" : ""].join(" ").toLocaleLowerCase().includes(query)) : visibleItems; return [...matches].sort((left, right) => left.serviceDate.localeCompare(right.serviceDate) || (left.eventStartLocal ?? "").localeCompare(right.eventStartLocal ?? "") || left.title.localeCompare(right.title)); }, [visibleItems, search, teams]);
  const visibleCalendarCount = [...calendarItems.values()].reduce((total, entries) => total + entries.length, 0);
  const rangeLabel = `${days[0]!.toLocaleDateString(undefined, { month: "short", day: "numeric", year: "numeric" })} - ${days.at(-1)!.toLocaleDateString(undefined, { month: "short", day: "numeric", year: "numeric" })}`;
  function chooseView(next: ActivityView) { try { window.localStorage.setItem(outreachActivityViewKey, next); } catch { /* The view still changes when browser storage is unavailable. */ } setView(next); }
  function toggleVisibility(mode: ActivityMode, visible: boolean) { const next = visible ? [...visibleModes, mode] : visibleModes.filter((item) => item !== mode); setVisibleModes(next); try { window.localStorage.setItem(outreachActivityVisibilityKey, JSON.stringify(next)); } catch { /* The visibility still changes when browser storage is unavailable. */ } }
  async function created(result: { publicationQueue?: { reason?: string; message?: string } }) { await onChanged(); setNotice(result.publicationQueue?.reason === "queue_failed" ? { tone: "error", text: result.publicationQueue.message ?? "Activity saved, but publication was not queued. Use Publish or Resend from the activity." } : { tone: "success", text: "Dated Outreach activity created." }); setCreating(false); }
  const openActivity = (id: string) => setSelectedActivityId(id);
  return <div className="outreach-stack">
    <section className="meeting-browser-controls outreach-activity-browser-controls ui-card" aria-label="Outreach activity browser controls" data-walkthrough="outreach-activities"><fieldset className="meeting-view-toggle"><legend>Activity view</legend><div><label className={view === "calendar" ? "selected" : ""}><input type="radio" name="outreach-activity-view" value="calendar" checked={view === "calendar"} onChange={() => chooseView("calendar")} /><BrowserViewIcon view="calendar" /><span className="meeting-view-label">Calendar</span></label><label className={view === "table" ? "selected" : ""}><input type="radio" name="outreach-activity-view" value="table" checked={view === "table"} onChange={() => chooseView("table")} /><BrowserViewIcon view="table" /><span className="meeting-view-label">Table</span></label></div></fieldset><div className="outreach-activity-picker-group"><label className="meeting-browser-select" data-walkthrough="outreach-staff-exception"><span>Activity</span><select className="ui-control ui-native-select" value="" onChange={(event) => { if (event.target.value) openActivity(event.target.value); }}><option value="">Choose an activity</option>{items.map((item) => <option key={item.id} value={item.id}>{item.serviceDate} - {item.title}</option>)}</select></label><ActivityVisibilityFilter visibleModes={visibleModes} onChange={toggleVisibility} /></div><button className="ui-button ui-button--primary" type="button" aria-haspopup="dialog" data-walkthrough="outreach-submission-sources" onClick={() => setCreating(true)}>Create activity</button></section>
    {view === "calendar" ? <section className="rolling-calendar dashboard-meeting-calendar outreach-activity-calendar ui-card" aria-labelledby="outreach-activity-calendar-title"><div className="section-heading calendar-heading"><div><h2 id="outreach-activity-calendar-title">Activity calendar</h2><p aria-live="polite">{rangeLabel}</p></div><div className="calendar-navigation"><button className="ui-button" type="button" aria-label="Show previous five weeks of Outreach activities" onClick={() => setCalendarOffset((value) => value - 1)}>←</button><button className="ui-button" type="button" disabled={calendarOffset === 0} onClick={() => setCalendarOffset(0)}>Today</button><button className="ui-button" type="button" aria-label="Show next five weeks of Outreach activities" onClick={() => setCalendarOffset((value) => value + 1)}>→</button></div></div>{visibleCalendarCount === 0 && <p className="empty-state calendar-empty-state">No selected activity types are scheduled in this five-week range.</p>}<div className="calendar-weekdays" aria-hidden="true">{["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"].map((day) => <span key={day}>{day}</span>)}</div><div className="calendar-grid">{days.map((day) => { const today = dayKey(day) === context.today; const entries = calendarItems.get(dayKey(day)) ?? []; return <article key={dayKey(day)} className={`calendar-day${today ? " today" : ""}`}><header><span>{day.toLocaleDateString(undefined, { month: "short" })}</span><strong>{day.getDate()}</strong></header>{entries.map((item) => <button className="outreach-activity-calendar-entry" key={item.id} type="button" aria-label={`Open ${item.title}`} onClick={() => openActivity(item.id)} title={`${item.title}, ${item.serviceDate}, ${activityTypeLabel(item.mode)}`}><span>{item.eventStartLocal ?? activityTypeLabel(item.mode)}</span>{item.title}</button>)}</article>; })}</div></section> : <section className="task-card meeting-directory outreach-activity-directory ui-card" aria-labelledby="outreach-activity-table-title"><div className="table-toolbar"><div className="meeting-directory-heading"><h2 id="outreach-activity-table-title">Activity table</h2><p>{filtered.length} of {visibleItems.length} shown</p></div><label>Search activities<input type="search" value={search} onChange={(event) => setSearch(event.target.value)} placeholder="Title, date, type, location, labels" /></label></div><div className="responsive-table"><table className="ui-table"><thead><tr><th><span className="visually-hidden">Open</span></th><th>Title</th><th>Date</th><th>Type</th><th>Schedule</th><th>Supported team</th><th>Labels</th><th>Status</th></tr></thead><tbody>{filtered.map((item) => { const status = item.archived ? "Archived" : "Active"; const type = activityTypeLabel(item.mode); return <tr className="outreach-activity-table-row" key={item.id} tabIndex={0} aria-label={`Open ${item.title}`} onClick={(event) => { if (!(event.target as Element).closest(".meeting-selection")) openActivity(item.id); }} onKeyDown={(event) => { if (event.target === event.currentTarget && (event.key === "Enter" || event.key === " ")) { event.preventDefault(); openActivity(item.id); } }}><td><button className="ui-button meeting-selection" type="button" aria-label={selectedActivityId === item.id ? `Close ${item.title}` : `Open ${item.title}`} aria-pressed={selectedActivityId === item.id} onClick={() => setSelectedActivityId(selectedActivityId === item.id ? "" : item.id)}><span aria-hidden="true">{selectedActivityId === item.id ? "×" : "→"}</span></button></td><td className="meeting-title-cell"><strong>{item.title}</strong><span className="meeting-mobile-details"><span><small>Date</small>{item.serviceDate}</span><span><small>Type</small>{type}</span><span><small>Status</small>{status}</span></span></td><td>{item.serviceDate}</td><td>{type}</td><td>{item.mode === "event" ? item.eventStartLocal && item.eventEndLocal ? `${item.eventStartLocal} to ${item.eventEndLocal}` : "Not scheduled" : "Not applicable"}</td><td>{item.teamId ? teams.find((team) => team.id === item.teamId)?.name ?? "Supported team" : "None"}</td><td>{item.labels.length ? item.labels.map((label) => label.name).join(", ") : "None"}</td><td>{status}</td></tr>; })}</tbody></table>{filtered.length === 0 && <p className="empty-state">{!visibleModes.length ? "No activity types are selected." : visibleItems.length ? "No activities match this search." : items.length ? "No activities match the visibility filters." : "No Outreach activities yet."}</p>}</div></section>}
    <ActivityCreationDialog open={creating} labels={activeLabels} teams={teams} context={context} onClose={() => setCreating(false)} onCreated={created} />
    </div>;
}

function ActivityVisibilityFilter({ visibleModes, onChange }: { visibleModes: ActivityMode[]; onChange: (mode: ActivityMode, visible: boolean) => void }) {
  return <details className="outreach-activity-visibility"><summary><span>Visibility</span><small>{visibleModes.length} of {activityTypes.length}</small></summary><fieldset className="ui-card"><legend className="visually-hidden">Show activity types</legend>{activityTypes.map((item) => <label className="checkbox-field" key={item.value}><input className="ui-checkbox" type="checkbox" checked={visibleModes.includes(item.value)} onChange={(event) => onChange(item.value, event.target.checked)} /> {item.value === "event" ? "Scheduled events" : item.label}</label>)}</fieldset></details>;
}

function ActivityCreationDialog({ open, labels, teams, context, onClose, onCreated }: { open: boolean; labels: OutreachLabel[]; teams: Team[]; context: EntryContext; onClose: () => void; onCreated: (result: { publicationQueue?: { reason?: string; message?: string } }) => Promise<void> }) {
  const initialDraft = () => ({ mode: "event" as ActivityMode, labelIds: [] as string[], teamId: "", serviceDate: context.today, title: "", description: "", location: "", impactRelevant: true });
  const emptySchedule = (): OutreachEventSchedule => ({ eventStartLocal: null, eventEndLocal: null, eventStartOccurrence: null, eventEndOccurrence: null });
  const dialog = useRef<HTMLElement>(null); const errorAlert = useRef<HTMLParagraphElement>(null); const [draft, setDraft] = useState(initialDraft); const [schedule, setSchedule] = useState<OutreachEventSchedule>(emptySchedule); const [saving, setSaving] = useState(false); const [error, setError] = useState("");
  const reset = () => { setDraft(initialDraft()); setSchedule(emptySchedule()); setError(""); };
  const close = () => { if (saving) return; reset(); onClose(); };
  useModalFocus(dialog, open, saving, close);
  useEffect(() => { if (error) errorAlert.current?.focus(); }, [error]);
  async function create(event: React.FormEvent) { event.preventDefault(); setError(""); setSaving(true); try { const result = await api<{ publicationQueue?: { reason?: string; message?: string } }>("/admin/hours/activities", { method: "POST", body: JSON.stringify({ ...activityPayload(draft), ...(draft.mode === "event" ? schedule : {}) }) }); await onCreated(result); reset(); onClose(); } catch (caught) { setError((caught as Error).message); } finally { setSaving(false); } }
  if (!open) return null;
  return <div className="dialog-backdrop"><section ref={dialog} className="meeting-create-dialog outreach-activity-create-dialog ui-dialog" role="dialog" aria-modal="true" aria-labelledby="outreach-create-activity-title" aria-describedby={`outreach-create-activity-description${error ? " outreach-create-activity-error" : ""}`} tabIndex={-1}><div className="dialog-heading"><div><h2 id="outreach-create-activity-title">Create Outreach activity</h2><p id="outreach-create-activity-description">Add one dated activity without leaving the Outreach workspace.</p></div><button className="ui-button" type="button" aria-label="Close create activity" disabled={saving} onClick={close}>×</button></div><form id="outreach-create-activity-form" className="meeting-create-form outreach-activity-create-form ui-form" aria-busy={saving} onSubmit={create}><label>Activity type<select className="ui-native-select" data-modal-initial-focus required value={draft.mode} onChange={(event) => { const mode = event.target.value as ActivityMode; setDraft({ ...draft, mode, teamId: "" }); if (mode !== "event") setSchedule(emptySchedule()); }}>{activityTypes.map((item) => <option key={item.value} value={item.value}>{item.label}</option>)}</select></label>{draft.mode === "team" && <label>Supported team<select className="ui-native-select" required value={draft.teamId} onChange={(event) => setDraft({ ...draft, teamId: event.target.value })}><option value="">Choose team</option>{teams.map((item) => <option key={item.id} value={item.id}>{item.name}</option>)}</select></label>}<label>Service date<input type="date" required value={draft.serviceDate} onChange={(event) => setDraft({ ...draft, serviceDate: event.target.value })} /></label>{draft.mode === "event" && <OutreachEventScheduleFields date={draft.serviceDate} timeZone={context.timeZone} value={schedule} onChange={setSchedule} disabled={saving} />}<label>Activity title<input required maxLength={150} value={draft.title} onChange={(event) => setDraft({ ...draft, title: event.target.value })} /></label><label>Description<textarea maxLength={4000} value={draft.description} onChange={(event) => setDraft({ ...draft, description: event.target.value })} /></label><label>Location<input maxLength={300} value={draft.location} onChange={(event) => setDraft({ ...draft, location: event.target.value })} /></label><LabelPicker labels={labels} selected={draft.labelIds} onChange={(labelIds) => setDraft({ ...draft, labelIds })} /><label className="checkbox-field"><input type="checkbox" checked={draft.impactRelevant} onChange={(event) => setDraft({ ...draft, impactRelevant: event.target.checked })} /> Impact relevant</label>{error && <p ref={errorAlert} id="outreach-create-activity-error" className="inline-messages error" role="alert" tabIndex={-1}>{error}</p>}<div className="dialog-actions"><button className="ui-button" type="button" disabled={saving} onClick={close}>Cancel</button><button className="ui-button ui-button--primary" disabled={saving || draft.mode === "team" && !draft.teamId}>{saving ? "Creating..." : "Create activity"}</button></div></form></section></div>;
}

function LabelPicker({ labels, selected, onChange }: { labels: OutreachLabel[]; selected: string[]; onChange: (ids: string[]) => void }) {
  return <fieldset className="outreach-fieldset"><legend>Outreach labels (optional)</legend>{labels.length ? labels.map((label) => <label className="checkbox-field" key={label.id}><input className="ui-checkbox" type="checkbox" checked={selected.includes(label.id)} onChange={(event) => onChange(event.target.checked ? [...selected, label.id] : selected.filter((id) => id !== label.id))} /> {label.name}</label>) : <p className="field-help">No Outreach labels yet. Create one from the Outreach Settings tab or Settings &gt; Outreach, or leave this activity unlabeled.</p>}</fieldset>;
}

function OutreachCatalogPanels({ labels, teams, onTeamsChanged, onLabelCreated, onLabelChange, setNotice }: { labels: OutreachLabel[]; teams: Team[]; onTeamsChanged: () => Promise<void>; onLabelCreated: (item: OutreachLabel) => void; onLabelChange: (item: OutreachLabel) => void; setNotice: (value: { tone: "success" | "error"; text: string }) => void }) {
  return <div className="outreach-catalog-settings"><TeamPanel items={teams} onChanged={onTeamsChanged} setNotice={setNotice} /><LabelManager items={labels} onCreated={onLabelCreated} onChange={onLabelChange} setNotice={setNotice} /></div>;
}

export function OutreachCatalogSettings() {
  const [labels, setLabels] = useState<OutreachLabel[]>([]); const [teams, setTeams] = useState<Team[]>([]); const [busy, setBusy] = useState(true); const [notice, setNotice] = useState<{ tone: "success" | "error"; text: string }>(); const noticeRef = useRef<HTMLParagraphElement>(null);
  async function load() { setBusy(true); try { const [labelPage, teamPage] = await Promise.all([api<Page<OutreachLabel>>("/admin/hours/labels?archived=all&limit=100"), api<Page<Team>>("/admin/hours/teams?archived=all&limit=100")]); setLabels(labelPage.items); setTeams(teamPage.items); } catch (error) { setNotice({ tone: "error", text: (error as Error).message }); } finally { setBusy(false); } }
  useEffect(() => { void load(); }, []);
  useEffect(() => { if (notice) window.requestAnimationFrame(() => noticeRef.current?.focus()); }, [notice]);
  const updateLabel = (updated: OutreachLabel) => setLabels((current) => current.map((item) => item.id === updated.id ? updated : item));
  return <div className="outreach-stack">{notice && <p ref={noticeRef} tabIndex={-1} className="ui-status settings-notice" data-tone={notice.tone} role={notice.tone === "error" ? "alert" : "status"}>{notice.text}</p>}{busy ? <p className="ui-status" role="status">Loading Outreach settings...</p> : <OutreachCatalogPanels labels={labels} teams={teams} onTeamsChanged={load} onLabelCreated={(created) => setLabels((current) => [...current, created])} onLabelChange={updateLabel} setNotice={setNotice} />}</div>;
}

function LabelManager({ items, onCreated, onChange, setNotice }: { items: OutreachLabel[]; onCreated: (item: OutreachLabel) => void; onChange: (item: OutreachLabel) => void; setNotice: (value: { tone: "success" | "error"; text: string }) => void }) {
  const [adding, setAdding] = useState(false); const [name, setName] = useState(""); const [saving, setSaving] = useState(false); const dialog = useRef<HTMLElement>(null);
  const close = () => { setAdding(false); setName(""); };
  useModalFocus(dialog, adding, saving, close);
  async function create(event: React.FormEvent) { event.preventDefault(); if (!name.trim()) return; setSaving(true); try { const created = await api<OutreachLabel>("/admin/hours/labels", { method: "POST", body: JSON.stringify({ name: name.trim() }) }); onCreated(created); setNotice({ tone: "success", text: "Outreach label created." }); close(); } catch (error) { setNotice({ tone: "error", text: (error as Error).message }); } finally { setSaving(false); } }
  return <section className="outreach-label-page outreach-stack" aria-labelledby="outreach-labels-title"><div className="panel-heading outreach-catalog-heading"><div><h2 id="outreach-labels-title">Outreach labels</h2><p>Create labels here, then assign one or more labels to an activity.</p></div><button className="ui-button ui-button--primary" type="button" aria-haspopup="dialog" aria-expanded={adding} onClick={() => setAdding(true)}>Add label</button></div><div className="ui-card outreach-stack">{items.map((item) => <LabelManagerRow key={`${item.id}:${item.revision}`} item={item} onChange={onChange} setNotice={setNotice} />)}{!items.length && <p>No Outreach labels yet.</p>}</div>{adding && <div className="dialog-backdrop"><section ref={dialog} className="meeting-management-dialog outreach-catalog-dialog ui-dialog" role="dialog" aria-modal="true" aria-labelledby="outreach-add-label-title" tabIndex={-1}><div className="dialog-heading"><div><h2 id="outreach-add-label-title">Add Outreach label</h2><p>Create a reusable label for Outreach activities.</p></div><button className="ui-button" type="button" aria-label="Close add label dialog" disabled={saving} onClick={close}>×</button></div><form className="ui-form outreach-stack" onSubmit={(event) => void create(event)}><label>Label name<input data-modal-initial-focus required maxLength={100} value={name} onChange={(event) => setName(event.target.value)} /></label><div className="dialog-actions"><button className="ui-button" type="button" disabled={saving} onClick={close}>Cancel</button><button className="ui-button ui-button--primary" disabled={saving || !name.trim()}>{saving ? "Adding..." : "Add label"}</button></div></form></section></div>}</section>;
}

function LabelManagerRow({ item, onChange, setNotice }: { item: OutreachLabel; onChange: (item: OutreachLabel) => void; setNotice: (value: { tone: "success" | "error"; text: string }) => void }) {
  const [name, setName] = useState(item.name); const [saving, setSaving] = useState(false);
  async function update(archived: boolean) { setSaving(true); try { const updated = await api<OutreachLabel>(`/admin/hours/labels/${encodeURIComponent(item.id)}`, { method: "PATCH", body: JSON.stringify({ revision: item.revision, name: name.trim(), archived }) }); onChange(updated); setNotice({ tone: "success", text: archived ? "Outreach label archived." : item.archived ? "Outreach label reopened." : "Outreach label renamed." }); } catch (error) { setNotice({ tone: "error", text: (error as Error).message }); } finally { setSaving(false); } }
  return <div className="ui-form outreach-label-manager-row"><label>Label name<input maxLength={100} value={name} onChange={(event) => setName(event.target.value)} /></label><div className="module-actions"><button className="ui-button" type="button" disabled={saving || !name.trim() || name.trim() === item.name} onClick={() => void update(item.archived)}>Save name</button><button className="ui-button" type="button" disabled={saving || !name.trim()} onClick={() => void update(!item.archived)}>{item.archived ? "Reopen" : "Archive"}</button></div></div>;
}

function CorrectionInbox({ items, onOpenActivity }: { items: Correction[]; onOpenActivity: (id: string) => void }) {
  const [open, setOpen] = useState(false);
  return <div className="outreach-correction-inbox" data-walkthrough="outreach-corrections"><button className="ui-button" type="button" aria-haspopup="dialog" aria-expanded={open} onClick={() => setOpen((value) => !value)}>Corrections <span className="ui-status" data-tone={items.length ? "warning" : "neutral"}>{items.length}</span></button>{open && <div className="ui-card outreach-correction-inbox-panel" role="dialog" aria-label="Open Outreach corrections"><div className="outreach-row"><strong>Open corrections</strong><button className="ui-button" type="button" onClick={() => setOpen(false)}>Close</button></div>{items.map((item) => { const activityId = item.activityId ?? item.entryActivityId; return <div className="outreach-correction-inbox-item" key={item.id}><strong>{item.memberName}</strong><span>{item.activityTitle ?? "Activity unavailable"}</span><button className="ui-button" type="button" disabled={!activityId} onClick={() => { if (activityId) onOpenActivity(activityId); setOpen(false); }}>Review in activity</button></div>; })}{!items.length && <p>No correction requests need review.</p>}</div>}</div>;
}

function ActivityDetail({ activity, activities, labels, members, windows, corrections, publication, publicationProviders, context, onChanged, close, setNotice }: { activity: Activity; activities: Activity[]; labels: OutreachLabel[]; members: Member[]; windows: ReopenWindow[]; corrections: Correction[]; publication?: Publication; publicationProviders: PublicationProviders; context: EntryContext; onChanged: () => Promise<void>; close: () => void; setNotice: (value: { tone: "success" | "error"; text: string }) => void }) {
  const [showManual, setShowManual] = useState(false); const [labelIds, setLabelIds] = useState(activity.labelIds); const [schedule, setSchedule] = useState<OutreachEventSchedule>({ eventStartLocal: activity.eventStartLocal, eventEndLocal: activity.eventEndLocal, eventStartOccurrence: activity.eventStartOccurrence, eventEndOccurrence: activity.eventEndOccurrence }); const [saving, setSaving] = useState(false); const open = corrections.filter((item) => item.status === "open"); const resolved = corrections.filter((item) => item.status === "resolved");
  const scheduleChanged = activity.mode === "event" && (schedule.eventStartLocal !== activity.eventStartLocal || schedule.eventEndLocal !== activity.eventEndLocal || schedule.eventStartOccurrence !== activity.eventStartOccurrence || schedule.eventEndOccurrence !== activity.eventEndOccurrence);
  async function saveDetails() { setSaving(true); try { const result = await api<{ publicationQueue?: { reason?: string; message?: string } }>(`/admin/hours/activities/${encodeURIComponent(activity.id)}`, { method: "PATCH", body: JSON.stringify({ revision: activity.revision, labelIds, ...(activity.mode === "event" ? schedule : {}) }) }); await onChanged(); setNotice(result.publicationQueue?.reason === "queue_failed" ? { tone: "error", text: result.publicationQueue.message ?? "Activity saved, but publication was not queued. Use Publish or Resend from the activity." } : { tone: "success", text: "Activity details updated." }); } catch (error) { setNotice({ tone: "error", text: (error as Error).message }); } finally { setSaving(false); } }
  return <article className="outreach-stack" aria-labelledby={`outreach-activity-${activity.id}`}>
    <header className="meeting-detail-heading"><div><span className="ui-status" data-tone={activity.archived ? "neutral" : "success"}>{activity.archived ? "Archived" : activityTypeLabel(activity.mode)}</span><h1 id={`outreach-activity-${activity.id}`}>{activity.title}</h1></div><div className="meeting-detail-actions"><button className="ui-button" type="button" onClick={close}>Close activity</button>{!activity.archived && activity.serviceDate <= context.today && <button className="ui-button" type="button" aria-expanded={showManual} onClick={() => setShowManual((value) => !value)}>Add member participation</button>}<button className="ui-button ui-button--primary" type="button" onClick={() => void onChanged().catch(() => undefined)}>Refresh participation</button></div></header>
    <dl className="meeting-summary ui-card" aria-label="Activity summary"><div><dt>Service date</dt><dd>{activity.serviceDate}</dd></div><div><dt>Event times</dt><dd>{activity.eventStartLocal && activity.eventEndLocal ? `${activity.eventStartLocal} to ${activity.eventEndLocal}` : "Not set"}</dd></div><div><dt>Location</dt><dd>{activity.location || "Not set"}</dd></div><div><dt>Type</dt><dd>{activityTypeLabel(activity.mode)}</dd></div><div><dt>Labels</dt><dd>{activity.labels.map((label) => label.name).join(", ") || "None"}</dd></div><div className="meeting-summary-notes"><dt>Description</dt><dd>{activity.description || "No description"}</dd></div></dl>
    {showManual && <ManualEntryForm activity={activity} members={members} context={context} onChanged={onChanged} onCancel={() => setShowManual(false)} setNotice={setNotice} />}
    <ActivityParticipation activityId={activity.id} timeZone={context.timeZone} />
    {(open.length > 0 || resolved.length > 0) && <section className="ui-card outreach-stack" aria-labelledby={`outreach-corrections-${activity.id}`}><h2 id={`outreach-corrections-${activity.id}`}>Correction requests</h2>{open.map((item) => <CorrectionCard key={`${item.id}:${item.revision}`} item={item} activities={activities} members={members} context={context} onChanged={onChanged} setNotice={setNotice} />)}{resolved.length > 0 && <details><summary>Resolved correction history ({resolved.length})</summary><div className="outreach-stack">{resolved.map((item) => <article className="ui-card outreach-row" key={item.id}><div><strong>{item.memberName} - {item.resolutionAction ?? "resolved"}</strong><p>{item.createdAt}</p><small>{item.resolutionNote}</small></div></article>)}</div></details>}</section>}
    <section className="ui-card outreach-stack" aria-labelledby={`outreach-labels-${activity.id}`}><h2 id={`outreach-labels-${activity.id}`}>Activity details</h2>{activity.mode === "event" && <OutreachEventScheduleFields date={activity.serviceDate} timeZone={context.timeZone} value={schedule} onChange={setSchedule} disabled={saving || activity.archived} />}<LabelPicker labels={labels} selected={labelIds} onChange={setLabelIds} /><button className="ui-button" type="button" disabled={saving || !scheduleChanged && labelIds.join("|") === activity.labelIds.join("|")} onClick={() => void saveDetails()}>Save activity details</button></section>
    {activity.mode === "event" && <section className="ui-card outreach-stack"><h2>Event publication</h2><ActivityPublicationControls activity={activity} publication={publication} providers={publicationProviders} onChanged={onChanged} setNotice={setNotice} /></section>}
    <ActivityWindowControls activity={activity} items={windows} context={context} onChanged={onChanged} setNotice={setNotice} />
  </article>;
}

function ActivityParticipation({ activityId, timeZone }: { activityId: string; timeZone: string }) {
  const [entries, setEntries] = useState<Entry[]>([]); const [loading, setLoading] = useState(true); const [error, setError] = useState(""); const [expanded, setExpanded] = useState<string[]>([]);
  useEffect(() => {
    const controller = new AbortController(); setLoading(true); setEntries([]); setError(""); setExpanded([]);
    void loadOutreachPages<Entry>(`/admin/hours/entries?activityId=${encodeURIComponent(activityId)}&status=all&limit=100`, controller.signal).then((items) => { if (!controller.signal.aborted) setEntries(items); }).catch((caught) => { if (!controller.signal.aborted) setError((caught as Error).message); }).finally(() => { if (!controller.signal.aborted) setLoading(false); });
    return () => controller.abort();
  }, [activityId]);
  const groups = useMemo(() => groupOutreachParticipation(entries), [entries]);
  const countedMinutes = groups.reduce((total, member) => total + member.minutes, 0); const counted = groups.reduce((total, member) => total + member.counted, 0);
  return <section className="attendance-card ui-card outreach-stack outreach-participation-card" aria-labelledby="outreach-participation-title"><div className="panel-heading"><h2 id="outreach-participation-title">Logged participation</h2>{!loading && !error && <span className="progress-count">{(countedMinutes / 60).toFixed(2)} hours - {counted} counted {counted === 1 ? "entry" : "entries"}</span>}</div>
    {loading ? <p className="ui-status" role="status">Loading all participation for this activity...</p> : error ? <p className="ui-status" data-tone="error" role="alert">{error} Totals are unavailable until every page loads. Use Refresh participation to retry.</p> : !groups.length ? <p className="empty-state">No participation submissions for this activity yet.</p> : <div className="responsive-table"><table className="ui-table outreach-participation-table" aria-label="Activity participation"><thead><tr><th>Member</th><th>Hours</th><th>Counted entries</th><th>Submissions</th></tr></thead><tbody>{groups.map((member) => <ParticipationMember key={member.memberId} member={member} timeZone={timeZone} expanded={expanded.includes(member.memberId)} onToggle={() => setExpanded((current) => current.includes(member.memberId) ? current.filter((id) => id !== member.memberId) : [...current, member.memberId])} />)}</tbody></table></div>}
  </section>;
}

function ParticipationMember({ member, timeZone, expanded, onToggle }: { member: ReturnType<typeof groupOutreachParticipation<Entry>>[number]; timeZone: string; expanded: boolean; onToggle: () => void }) {
  const detailId = `outreach-participation-${member.memberId}`;
  return <><tr><th scope="row"><strong>{member.name}</strong><small>{member.externalId}</small></th><td>{(member.minutes / 60).toFixed(2)}</td><td>{member.counted}</td><td><button className="ui-button" type="button" aria-expanded={expanded} aria-controls={detailId} onClick={onToggle}>{expanded ? "Hide" : "View"} submissions ({member.entries.length})<span className="visually-hidden"> for {member.name}</span></button></td></tr>{expanded && <tr id={detailId}><td colSpan={4}><div className="outreach-stack outreach-participation-submissions">{member.entries.map((entry) => <article className="ui-card outreach-stack" key={entry.id}>
    <div className="outreach-row"><strong>{entry.serviceDate} - {entry.startLocal} to {entry.endLocal}</strong><span className="ui-status" data-tone={entry.status === "counted" ? "success" : "neutral"}>{entry.status === "counted" ? "Counted" : "Void - excluded from totals"}</span></div>
    <dl className="outreach-entry-summary"><div><dt>Duration</dt><dd>{(entry.durationMinutes / 60).toFixed(2)} hours ({entry.durationMinutes} minutes)</dd></div><div><dt>Source</dt><dd>{outreachEntrySource(entry.attribution)}</dd></div><div><dt>Revision</dt><dd>{entry.revision}</dd></div><div><dt>Time zone</dt><dd>{entry.timeZone ?? timeZone}{entry.startOccurrence ? ` - start: ${entry.startOccurrence} occurrence` : ""}{entry.endOccurrence ? ` - end: ${entry.endOccurrence} occurrence` : ""}</dd></div></dl>{entry.taskNotes && <p><strong>Notes:</strong> {entry.taskNotes}</p>}{entry.staffReason && <p><strong>Staff reason:</strong> {entry.staffReason}</p>}
  </article>)}</div></td></tr>}</>;
}

function ActivityWindowControls({ activity, items, context, onChanged, setNotice }: { activity: Activity; items: ReopenWindow[]; context: EntryContext; onChanged: () => Promise<void>; setNotice: (value: { tone: "success" | "error"; text: string }) => void }) {
  const standardClosesOn = addCalendarDays(activity.serviceDate, context.reportingDays - 1); const older = activity.serviceDate < addCalendarDays(context.today, 1 - context.reportingDays); const future = activity.serviceDate > context.today; const active = items.find((item) => item.active); const latest = active ?? items[0]; const [hours, setHours] = useState(context.reopenHours); const [reason, setReason] = useState(""); const [saving, setSaving] = useState(false);
  async function create(event: React.FormEvent) { event.preventDefault(); setSaving(true); try { await api("/admin/hours/reopen-windows", { method: "POST", body: JSON.stringify({ activityId: activity.id, hours, reason, settingsRevision: context.revision }) }); await onChanged(); setNotice({ tone: "success", text: "Reporting window opened for this activity." }); } catch (error) { setNotice({ tone: "error", text: (error as Error).message }); } finally { setSaving(false); } }
  async function revoke() { if (!active) return; setSaving(true); try { await api(`/admin/hours/reopen-windows/${encodeURIComponent(active.id)}`, { method: "PATCH", body: JSON.stringify({ revision: active.revision, revoked: true }) }); await onChanged(); setNotice({ tone: "success", text: "Reporting window revoked for this activity." }); } catch (error) { setNotice({ tone: "error", text: (error as Error).message }); } finally { setSaving(false); } }
  const status = activity.archived ? "Archived - reporting closed" : active ? `Reopened - expires ${new Date(active.expiresMs).toLocaleString()}` : future ? `Scheduled - standard reporting opens ${activity.serviceDate} and closes ${standardClosesOn}` : older ? "Closed - eligible to reopen" : `Standard reporting open through ${standardClosesOn}`;
  return <section className="ui-card outreach-stack" aria-labelledby={`outreach-window-${activity.id}`}><h2 id={`outreach-window-${activity.id}`}>Reporting window</h2><p><strong>{status}</strong></p>{!active && latest && <small>Most recent window {latest.revoked ? "was revoked" : "expired"} at {new Date(latest.expiresMs).toLocaleString()}.</small>}{!activity.archived && active && <button className="ui-button" type="button" disabled={saving} onClick={() => void revoke()}>Revoke reporting window</button>}{!activity.archived && older && !active && <form className="ui-form outreach-stack" onSubmit={create}><label>Window length in hours<input type="number" min={1} max={168} required value={hours} onChange={(event) => setHours(Number(event.target.value))} /></label><label>Reason<textarea required maxLength={4000} value={reason} onChange={(event) => setReason(event.target.value)} /></label><button className="ui-button ui-button--primary" disabled={saving || !reason.trim()}>Reopen reporting for this activity</button></form>}</section>;
}

function ManualEntryForm({ activity, members, context, onChanged, onCancel, setNotice }: { activity: Activity; members: Member[]; context: EntryContext; onChanged: () => Promise<void>; onCancel: () => void; setNotice: (value: { tone: "success" | "error"; text: string }) => void }) {
  const [memberId, setMemberId] = useState(members[0]?.id ?? ""); const [startLocal, setStartLocal] = useState("09:00"); const [endLocal, setEndLocal] = useState("10:00"); const [startOccurrence, setStartOccurrence] = useState<CivilTimeOccurrence>(); const [endOccurrence, setEndOccurrence] = useState<CivilTimeOccurrence>(); const [taskNotes, setTaskNotes] = useState(""); const [staffReason, setStaffReason] = useState(""); const [saving, setSaving] = useState(false); const [pending, setPending] = useState<Record<string, unknown>>();
  const body = useMemo(() => ({ memberId, activityId: activity.id, serviceDate: activity.serviceDate, startLocal, endLocal, ...(startOccurrence ? { startOccurrence } : {}), ...(endOccurrence ? { endOccurrence } : {}), taskNotes, staffReason, expectedTimeZone: context.timeZone }), [memberId, activity.id, activity.serviceDate, startLocal, endLocal, startOccurrence, endOccurrence, taskNotes, staffReason, context.timeZone]);
  async function save(event?: React.FormEvent, exact?: Record<string, unknown>) { event?.preventDefault(); const submission = exact ?? { ...body, idempotencyKey: crypto.randomUUID() }; setPending(submission); setSaving(true); try { await api("/admin/hours/entries", { method: "POST", body: JSON.stringify(submission) }); setPending(undefined); await onChanged(); setNotice({ tone: "success", text: "Manual Outreach participation counted and attributed to Staff." }); } catch (error) { setNotice({ tone: "error", text: `${(error as Error).message} The same submission can be retried without double counting.` }); } finally { setSaving(false); } }
  return <form className="ui-card ui-form outreach-stack" onSubmit={(event) => void save(event)}><div><p className="kicker">Staff exception</p><h3>Add member participation</h3><p><strong>{activity.title}</strong> on {activity.serviceDate}. Start and end use {context.timeZone}. The server rejects overlaps and records whole minutes.</p></div><label>Member<select className="ui-native-select" required value={memberId} onChange={(event) => setMemberId(event.target.value)}>{members.map((item) => <option key={item.id} value={item.id}>{item.label} ({item.externalId}){item.active ? "" : " - inactive"}</option>)}</select></label><div className="outreach-time-grid"><OutreachClock label="Start time" date={activity.serviceDate} time={startLocal} zone={context.timeZone} occurrence={startOccurrence} onTime={setStartLocal} onOccurrence={setStartOccurrence} disabled={saving} /><OutreachClock label="End time" date={activity.serviceDate} time={endLocal} zone={context.timeZone} occurrence={endOccurrence} onTime={setEndLocal} onOccurrence={setEndOccurrence} disabled={saving} /></div><label>Staff reason<textarea required maxLength={4000} value={staffReason} onChange={(event) => setStaffReason(event.target.value)} /></label><label>Task notes (optional)<textarea maxLength={4000} value={taskNotes} onChange={(event) => setTaskNotes(event.target.value)} /></label><div className="module-actions"><button className="ui-button ui-button--primary" disabled={saving || !memberId || !staffReason.trim()}>Save manual participation</button>{pending && <button className="ui-button" type="button" disabled={saving} onClick={() => void save(undefined, pending)}>Retry exact submission</button>}<button className="ui-button" type="button" disabled={saving} onClick={onCancel}>Cancel</button></div></form>;
}

function SubmissionPanel({ items }: { items: Entry[] }) {
  const source = (item: Entry) => item.attribution === "linked_discord" ? "Linked Discord submission" : item.attribution === "self_asserted" ? "Public form submission" : "Staff-added entry";
  return <section className="outreach-stack" aria-labelledby="outreach-submission-log-title"><div><h2 id="outreach-submission-log-title">Submission Log</h2><p>Member participation normally arrives through the public form or a linked Discord account. Staff-added exceptions are clearly attributed and originate from the selected activity.</p></div>{items.map((item) => <article className="ui-card outreach-row" key={item.id}><div><strong>{item.memberName} - {item.activityTitle}</strong><p>{item.serviceDate}, {item.startLocal} to {item.endLocal} - {minutes(item.durationMinutes)}</p><small>{item.status === "counted" ? "Counted" : "Void"} - {source(item)}{item.staffReason ? ` - Staff reason: ${item.staffReason}` : ""}{item.taskNotes ? ` - ${item.taskNotes}` : ""}</small></div></article>)}{!items.length && <p>No participation submissions yet.</p>}</section>;
}

function CorrectionCard({ item, activities, members, context, onChanged, setNotice }: { item: Correction; activities: Activity[]; members: Member[]; context: EntryContext; onChanged: () => Promise<void>; setNotice: (value: { tone: "success" | "error"; text: string }) => void }) {
  const [selectedEntry, setSelectedEntry] = useState<Entry>();
  const entryId = selectedEntry?.id ?? item.entryId; const entryRevision = selectedEntry?.revision ?? item.entryRevision;
  const canRevise = Boolean(entryId && (selectedEntry?.status ?? item.entryStatus) === "counted" && entryRevision !== null);
  const [action, setAction] = useState<"acknowledged" | "dismissed" | "corrected" | "voided">(canRevise ? "corrected" : "acknowledged"); const [note, setNote] = useState(""); const [memberId, setMemberId] = useState(item.entryMemberId ?? ""); const [activityId, setActivityId] = useState(item.activityId ?? item.entryActivityId ?? ""); const [startLocal, setStartLocal] = useState(item.startLocal ?? "09:00"); const [endLocal, setEndLocal] = useState(item.endLocal ?? "10:00"); const [startOccurrence, setStartOccurrence] = useState<CivilTimeOccurrence | undefined>(item.startOccurrence ?? undefined); const [endOccurrence, setEndOccurrence] = useState<CivilTimeOccurrence | undefined>(item.endOccurrence ?? undefined); const [taskNotes, setTaskNotes] = useState(item.taskNotes ?? ""); const [saving, setSaving] = useState(false); const activity = activities.find((candidate) => candidate.id === activityId);
  function chooseEntry(entry?: Entry) { setSelectedEntry(entry); setAction(entry?.status === "counted" ? "corrected" : "acknowledged"); setMemberId(entry?.memberId ?? ""); setActivityId(entry?.activityId ?? item.activityId ?? ""); setStartLocal(entry?.startLocal ?? "09:00"); setEndLocal(entry?.endLocal ?? "10:00"); setStartOccurrence(entry?.startOccurrence ?? undefined); setEndOccurrence(entry?.endOccurrence ?? undefined); setTaskNotes(entry?.taskNotes ?? ""); }
  async function resolve(event: React.FormEvent) {
    event.preventDefault(); const body: Record<string, unknown> = { action, note, requestRevision: item.revision };
    if (action === "voided") Object.assign(body, { entryRevision, ...(selectedEntry ? { entryId } : {}) });
    if (action === "corrected") Object.assign(body, { entryRevision, ...(selectedEntry ? { entryId } : {}), memberId, activityId, startLocal, endLocal, ...(startOccurrence ? { startOccurrence } : {}), ...(endOccurrence ? { endOccurrence } : {}), taskNotes });
    setSaving(true); try { await api(`/admin/hours/corrections/${encodeURIComponent(item.id)}/resolve`, { method: "POST", body: JSON.stringify(body) }); await onChanged(); setNotice({ tone: "success", text: action === "corrected" ? "Correction applied as one immutable entry revision." : action === "voided" ? "Entry voided through the correction workflow." : "Correction request resolved without changing participation totals." }); } catch (error) { setNotice({ tone: "error", text: (error as Error).message }); } finally { setSaving(false); }
  }
  return <form className="ui-card ui-form outreach-stack" onSubmit={resolve}>
    <div><strong>{item.memberName} ({item.externalId})</strong><p>{item.channel === "discord" ? "Linked Discord request" : "Public form request"} - {item.activityTitle ?? item.claimedServiceDate ?? "Activity unavailable"}</p><blockquote>{item.message}</blockquote></div>
    {!item.entryId && item.activityId && <CorrectionEntryPicker requestId={item.id} selectedId={selectedEntry?.id ?? ""} onChange={chooseEntry} disabled={saving} />}
    <label>Decision<select className="ui-native-select" value={action} onChange={(event) => setAction(event.target.value as typeof action)}><option value="acknowledged">Approve without changes</option><option value="dismissed">Reject request</option>{canRevise && <><option value="corrected">Approve and correct entry</option><option value="voided">Approve and void entry</option></>}</select></label>
    {action === "corrected" && <><label>Member<select className="ui-native-select" required value={memberId} disabled={Boolean(selectedEntry)} onChange={(event) => setMemberId(event.target.value)}>{members.map((member) => <option key={member.id} value={member.id}>{member.label} ({member.externalId})</option>)}</select></label><label>Dated activity<select className="ui-native-select" required value={activityId} disabled={Boolean(selectedEntry)} onChange={(event) => { setActivityId(event.target.value); setStartOccurrence(undefined); setEndOccurrence(undefined); }}>{activities.map((candidate) => <option key={candidate.id} value={candidate.id}>{candidate.serviceDate} - {candidate.title}</option>)}</select></label><div className="outreach-time-grid"><OutreachClock label="Corrected start time" date={activity?.serviceDate ?? ""} time={startLocal} zone={selectedEntry?.timeZone ?? context.timeZone} occurrence={startOccurrence} onTime={setStartLocal} onOccurrence={setStartOccurrence} disabled={saving || !activity} /><OutreachClock label="Corrected end time" date={activity?.serviceDate ?? ""} time={endLocal} zone={selectedEntry?.timeZone ?? context.timeZone} occurrence={endOccurrence} onTime={setEndLocal} onOccurrence={setEndOccurrence} disabled={saving || !activity} /></div><label>Corrected task notes<textarea maxLength={4000} value={taskNotes} onChange={(event) => setTaskNotes(event.target.value)} /></label></>}
    <label>Staff review note<textarea required maxLength={4000} value={note} onChange={(event) => setNote(event.target.value)} /></label><button className="ui-button ui-button--primary" disabled={saving || !note.trim() || action === "corrected" && (!canRevise || !memberId || !activityId)}>Resolve correction</button>
  </form>;
}

function CorrectionEntryPicker({ requestId, selectedId, onChange, disabled }: { requestId: string; selectedId: string; onChange: (entry?: Entry) => void; disabled: boolean }) {
  const [entries, setEntries] = useState<Entry[]>([]); const [loading, setLoading] = useState(true); const [error, setError] = useState("");
  useEffect(() => {
    const controller = new AbortController();
    void loadOutreachPages<Entry>(`/admin/hours/corrections/${encodeURIComponent(requestId)}/entries?limit=100`, controller.signal).then((items) => { if (!controller.signal.aborted) setEntries(items); }).catch((caught) => { if (!controller.signal.aborted) setError((caught as Error).message); }).finally(() => { if (!controller.signal.aborted) setLoading(false); });
    return () => controller.abort();
  }, [requestId]);
  return <div className="outreach-stack"><label>Participation entry to correct<select className="ui-native-select" disabled={disabled || loading || Boolean(error)} value={selectedId} onChange={(event) => onChange(entries.find((entry) => entry.id === event.target.value))}><option value="">Choose the affected submission</option>{entries.map((entry) => <option key={entry.id} value={entry.id}>{entry.serviceDate} - {entry.startLocal} to {entry.endLocal} - {(entry.durationMinutes / 60).toFixed(2)} hours - {entry.status}</option>)}</select></label>{loading ? <p className="ui-status" role="status">Loading this member's submissions for this activity...</p> : error ? <p className="ui-status" data-tone="error" role="alert">{error}</p> : !entries.length ? <p>No matching submissions. You can acknowledge or reject this request without changing recorded hours.</p> : <p className="field-help">Select the submission described in the request. Other members' submissions are not included.</p>}</div>;
}
